responses.text:
{
  "outcome": "revise",
  "issues": [
    {
      "kind": "contradiction",
      "severity": "critical",
      "description": "라인 6에서 중복 이름 신청 거부 시 참가 인원을 1 증가시키고 다음 정원 검사에 사용하도록 명시하여, 승인된 스코프 R-2(신청/취소 실패 시 무변경) 및 기술 제약(인원은 실제 참가 명단과 일치)과 정면으로 충돌하며 라인 3, 5의 설명과도 모순됩니다.",
      "suggestedDirection": "중복 신청 실패 시 인원을 증가시키지 않고 기존 명단과 정원/인원 계산을 온전히 유지하도록 라인 6의 규정을 수정해야 합니다.",
      "relatedRequirementId": "R-2"
    }
  ],
  "suggestions": [
    "중복 신청 거부 시 시도 횟수를 참가 인원에 반영하지 말고, 실패 시 명단과 계산이 유지되도록 규칙을 통일하십시오."
  ],
  "scopeViolation": true,
  "userJudgmentRequired": false,
  "qualityAssessment": {
    "version": 1,
    "requirements": [
      {
        "requirementId": "R-1",
        "status": "satisfied",
        "evidenceLines": [3, 5],
        "rationale": "정원 2명 제한 및 중복 이름 신청 거부 규칙이 이용 예시와 검증 규칙에 구체적으로 명시되어 있습니다."
      },
      {
        "requirementId": "R-2",
        "status": "missing",
        "evidenceLines": [6],
        "rationale": "라인 6에서 중복 이름 거부 시 참가 인원을 1 증가시키도록 규정하여 실패 시 참가 명단과 정원 계산을 변경하지 않아야 한다는 요구사항을 위반했습니다."
      }
    ],
    "checks": [
      {
        "id": "decision_provenance",
        "status": "satisfied",
        "evidenceLines": [8],
        "rationale": "스코프 확정 규칙과 설계 제안의 구분이 명확하며 임의의 결정을 사용자 확정으로 왜곡하지 않았습니다."
      },
      {
        "id": "scope_compliance",
        "status": "missing",
        "evidenceLines": [6],
        "rationale": "R-2 요구사항 및 '인원은 실제 참가 명단과 일치해야 한다'는 승인된 기술 제약을 위반하는 규칙이 포함되어 있습니다."
      },
      {
        "id": "behavior_and_errors",
        "status": "missing",
        "evidenceLines": [3, 5, 6],
        "rationale": "라인 3과 5에서는 실패 시 무변경 및 명단 길이 기반 인원 계산을 서술하지만 라인 6에서는 중복 실패 시 인원을 증가시켜 섹션 간 상태 전이 규칙이 모순됩니다."
      },
      {
        "id": "data_integrity",
        "status": "missing",
        "evidenceLines": [5, 6],
        "rationale": "중복 거부 시 인원을 증가시키면 '인원수 = 참가자 명단 길이'라는 컬렉션 불변식이 깨지게 됩니다."
      },
      {
        "id": "acceptance_criteria",
        "status": "satisfied",
        "evidenceLines": [3, 5],
        "rationale": "정상 등록, 정원 초과, 중복 등록, 취소 실패 등 구체적인 입력과 기대 결과가 명시되어 있습니다."
      },
      {
        "id": "revision_resolution",
        "status": "not_applicable",
        "evidenceLines": [],
        "rationale": "이전 리뷰 이력이나 settledDecisions에 등록된 수정 요청이 없으므로 해당 항목은 적용되지 않습니다."
      },
      {
        "id": "clarity",
        "status": "satisfied",
        "evidenceLines": [3, 5],
        "rationale": "사용자 관점의 예시가 먼저 제시되어 있고 용어가 이해하기 쉽게 기술되어 있습니다."
      }
    ]
  }
}
